-- sales_orders: 銷售訂單（一列一張訂單）：前 19 欄與正式環境 dbo.Orders 相同（欄名、順序、型別、值域），另加客戶、產業、城市、業務、成本與毛利
-- 20,000 rows, generated by scripts/demo-data/generate_demo_data.py
SET NOCOUNT ON;
SET XACT_ABORT ON;

IF OBJECT_ID(N'dbo.Orders', N'U') IS NOT NULL DROP TABLE dbo.Orders;

CREATE TABLE dbo.Orders (
    [OrderId] INT NOT NULL PRIMARY KEY,
    [CustomerId] INT NULL,
    [Region] NVARCHAR(20) NULL,
    [Country] NVARCHAR(50) NULL,
    [ProductCategory] NVARCHAR(50) NULL,
    [ProductName] NVARCHAR(100) NULL,
    [CustomerSegment] NVARCHAR(30) NULL,
    [SalesChannel] NVARCHAR(20) NULL,
    [SalesRepId] INT NULL,
    [OrderStatus] NVARCHAR(20) NULL,
    [PaymentMethod] NVARCHAR(30) NULL,
    [IsRenewal] BIT NULL,
    [Quantity] INT NULL,
    [UnitPrice] DECIMAL(12,2) NULL,
    [DiscountPct] DECIMAL(5,4) NULL,
    [Revenue] DECIMAL(14,2) NULL,
    [OrderDate] DATETIME2(0) NULL,
    [FiscalYear] INT NULL,
    [FiscalQuarter] NVARCHAR(6) NULL,
    [FiscalMonth] INT NULL,
    [CustomerName] NVARCHAR(100) NULL,
    [Industry] NVARCHAR(40) NULL,
    [CompanySize] NVARCHAR(20) NULL,
    [City] NVARCHAR(50) NULL,
    [SalesTeam] NVARCHAR(40) NULL,
    [SalesRepName] NVARCHAR(60) NULL,
    [LeadSource] NVARCHAR(30) NULL,
    [IsRefunded] BIT NULL,
    [ContractTermMonths] INT NULL,
    [SalesCycleDays] INT NULL,
    [UnitCost] DECIMAL(12,2) NULL,
    [Cost] DECIMAL(14,2) NULL,
    [GrossProfit] DECIMAL(14,2) NULL,
    [GrossMarginPct] DECIMAL(5,4) NULL
);

BEGIN TRANSACTION;





















COMMIT TRANSACTION;
PRINT N'dbo.Orders: 20,000 rows inserted.';
